const fs=require('fs');
const entry=fs.readFileSync('tmp-post-entry.ts','utf8').trimEnd();
const posts=fs.readFileSync('src/data/posts.ts','utf8');
const needle='  {\n    id: \"ai-capex-spend-concentration-2026q3\",';
